"/**
 * Pointsman API Service for Indian Railway Management System
 */

const API_BASE_URL = "http://localhost:5000/api";

/**
 * Fetch Pointsman Dashboard data
 * @returns {Promise<object>} Dashboard data object
 */
export async function getPointsmanDashboard() {
  const token = localStorage.getItem("token");
  if (!token) {
    throw new Error("Authorization token not found in localStorage. Please login again.");
  }

  const response = await fetch(`${API_BASE_URL}/pointsman/dashboard`, {
    method: "GET",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${token}`
    }
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.message || `Failed to fetch pointsman dashboard (Status: ${response.status})`);
  }

  const data = await response.json();
  if (!data.success) {
    throw new Error(data.message || "Failed to fetch pointsman dashboard data.");
  }

  return data.data;
}
"

