  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await getPointsmanDashboard();
      setDashboardData(data);

      try {
        const examStatus = await getExamStatus();
        setQuestionBankCount(examStatus.question_count);
        if (examStatus.has_active_attempt && examStatus.active_attempt) {
          setCbtAttempt(examStatus.active_attempt);
        }
      } catch (examErr) {
        console.warn("Could not check CBT exam status:", examErr);
      }
