    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fullName = dashboardData?.full_name || user?.name || "Pointsman User";
  const employeeId = dashboardData?.hrms_id || user?.hrmsId || "N/A";"

